import {Session,lessons} from './engine.js';
const $=id=>document.getElementById(id),s=new Session();
let mode='practice',phase='idle',elapsed=0,last=0,index=0,animation=null,wordTimer=null;
const rowsEN=['1234567890-=','qwertyuiop[]','asdfghjkl;\'','zxcvbnm,./'];
const rowsTH=['ๅ/-ภถุึคตจขช','ๆไำพะัีรนยบล','ฟหกดเ้่าสวง','ผปแอิืทมใฝ'];
const fingers=['นิ้วก้อยซ้าย','นิ้วนางซ้าย','นิ้วกลางซ้าย','นิ้วชี้ซ้าย','นิ้วชี้ซ้าย','นิ้วชี้ขวา','นิ้วชี้ขวา','นิ้วกลางขวา','นิ้วนางขวา','นิ้วก้อยขวา','นิ้วก้อยขวา','นิ้วก้อยขวา'];
function bestKey(){return `orbit-best-${$('language').value}-${$('level').value}-${mode}`;}
function loadBest(){try{return Number(localStorage.getItem(bestKey()))||0;}catch{return 0;}}
function showBest(){$('best').innerHTML=`${loadBest()} <small>คะแนน</small>`;}
function keyboard(){const rows=$('language').value==='th'?rowsTH:rowsEN;const expected=s.word[s.position];const shifted=document.getElementById("language").value==='th'&&expected==='์';const highlight=shifted?'ท':expected;$('keyboard').replaceChildren();let finger='วางนิ้วบนแถวเหย้า';rows.forEach((row,r)=>{const div=document.createElement('div');div.className='key-row';[...row].forEach((c,i)=>{const k=document.createElement('span');k.className='key'+(r===2&&(i===3||i===6)?' home':'');k.textContent=c;if($('hints').checked&&phase==='running'&&c===highlight){k.classList.add('next');finger=fingers[Math.max(0,r===0?i-1:i)]+(shifted?' + Shift ซ้าย':'');}div.append(k);});$('keyboard').append(div);});$('finger').textContent=$('hints').checked?finger:'ปิดตัวช่วย · ลองใช้ความจำของนิ้ว';}
function displayWord(){$('word').replaceChildren();[...s.word].forEach((c,i)=>{const span=document.createElement('span');span.textContent=c;span.className=i<s.position?'correct':i===s.position?'next':'';$('word').append(span);});keyboard();}
function nextWord(){const words=lessons[$('language').value][$('level').value];let word=words[index++%words.length];if(index%4===0&&Object.keys(s.mistakes).length){const weak=Object.entries(s.mistakes).sort((a,b)=>b[1]-a[1])[0][0];word=words.find(w=>w.includes(weak))||word;}s.setWord(word);$('typing').value='';displayWord();$('combo').textContent=s.combo>1?`✦ COMBO ×${s.combo} · ไปต่อได้เลย!`:'พิมพ์ให้ถูกทีละตัว · ไม่ต้องกด Enter';}
function stats(){$('score').textContent=String(s.score).padStart(4,'0');$('accuracy').innerHTML=`${s.hits+s.errors?s.accuracy():'—'}<small>%</small>`;$('wpm').innerHTML=`${s.wpm(elapsed)}<small>WPM</small>`;let t=mode==='timed'?Math.max(0,Math.ceil(60-elapsed)):Math.floor(elapsed);$('time').textContent=`${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`;$('destroyed').textContent=s.targets;}
function lock(active){$('language').disabled=active;$('level').disabled=active;document.querySelectorAll('.mode').forEach(b=>b.disabled=active);$('pause').disabled=!active;}
function start(){clearTimeout(wordTimer);s.reset();elapsed=0;index=0;phase='running';last=performance.now();lock(true);$('typing').disabled=false;$('typing').value='';$('typing').classList.remove('wrong');$('typing').placeholder='พิมพ์คำเป้าหมายที่นี่';$('start').innerHTML='จบการฝึก <span>□</span>';$('pause').textContent='Ⅱ พัก';$('target-label').textContent='เป้าหมายของคุณ';$('status').textContent='IN FLIGHT / กำลังฝึก';$('time-label').textContent=mode==='timed'?'เวลาที่เหลือ':'เวลาฝึก';$('feedback').textContent='พิมพ์ผิดลองใหม่ได้เลย ไม่ต้องลบ';nextWord();stats();$('typing').focus();}
function pause(){if(phase==='running'){phase='paused';$('typing').disabled=true;$('pause').textContent='▶ ฝึกต่อ';$('status').textContent='PAUSED / หยุดพัก';$('feedback').textContent='กดฝึกต่อ หรือ Esc เพื่อกลับเข้าภารกิจ';}else if(phase==='paused'){phase='running';last=performance.now();$('typing').disabled=false;$('pause').textContent='Ⅱ พัก';$('status').textContent='IN FLIGHT / กำลังฝึก';$('typing').focus();}keyboard();}
function finish(){if(phase==='idle')return;phase='idle';clearTimeout(wordTimer);lock(false);$('typing').disabled=true;$('start').innerHTML='เริ่มภารกิจ <span>↗</span>';$('status').textContent='COMPLETE / จบภารกิจ';try{localStorage.setItem(bestKey(),Math.max(loadBest(),s.score));}catch{}showBest();stats();$('result-caption').textContent=`ทำลาย ${s.targets} เป้าหมาย · ฝึกไป ${Math.floor(elapsed)} วินาที`;$('result-stats').innerHTML=`<div><strong>${s.score}</strong><span>คะแนน</span></div><div><strong>${s.accuracy()}%</strong><span>ความแม่นยำ</span></div><div><strong>${s.wpm(elapsed)}</strong><span>WPM</span></div>`;const weak=Object.entries(s.mistakes).sort((a,b)=>b[1]-a[1]).slice(0,4);$('review').textContent=weak.length?'ปุ่มที่ควรฝึกเพิ่ม: '+weak.map(([c,n])=>`${c} (${n} ครั้ง)`).join(' · '):s.hits?'แม่นยำมาก! ลองเพิ่มระดับ หรือปิดตัวช่วยในรอบถัดไป':'ลองเริ่มใหม่ แล้วพิมพ์คำที่ปรากฏบนจอ';$('results').showModal();keyboard();}
function consume(text){if(phase!=='running'||!text)return;for(const c of text){if(s.position===s.word.length)break;const result=s.type(c);$('typing').classList.toggle('wrong',!result.correct);$('feedback').textContent=result.correct?'ยอดเยี่ยม! มองจอแล้วพิมพ์ต่อได้เลย':`ลองอีกครั้ง · ปุ่มถัดไปคือ “${s.word[s.position]}”`;if(result.complete){animation?.shoot();$('flash').classList.remove('fire');void $('flash').offsetWidth;$('flash').classList.add('fire');wordTimer=setTimeout(()=>{if(phase!=='idle')nextWord();},280);}}$('typing').value=s.word.slice(0,s.position);displayWord();stats();}
$('typing').addEventListener('beforeinput',e=>{if(e.isComposing)return;if(e.inputType==='insertText'){e.preventDefault();consume(e.data);}else if(e.inputType==='insertFromPaste'||e.inputType.startsWith('delete'))e.preventDefault();});
$('typing').addEventListener('compositionend',e=>{consume(e.data);});
$('typing').addEventListener('input',e=>{if(!e.isComposing)$('typing').value=s.word.slice(0,s.position);});
$('typing').addEventListener('paste',e=>e.preventDefault());$('typing').addEventListener('drop',e=>e.preventDefault());
$('start').onclick=()=>phase==='idle'?start():finish();$('pause').onclick=pause;$('again').onclick=()=>{$('results').close();start();};$('close-results').onclick=()=>$('results').close();
document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('.mode').forEach(x=>x.classList.toggle('active',x===b));showBest();stats();});
['language','level'].forEach(id=>$(id).onchange=()=>{keyboard();showBest();});$('hints').onchange=keyboard;
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&phase!=='idle'){e.preventDefault();pause();}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&phase==='running')pause();});
setInterval(()=>{const now=performance.now();if(phase==='running'){elapsed+=(now-last)/1000;if(mode==='timed'&&elapsed>=60){elapsed=60;finish();}stats();}last=now;},100);
keyboard();showBest();
import('./scene.js').then(m=>{animation=m.createScene($('scene'));}).catch(()=>{$('feedback').textContent='ไม่สามารถเปิดฉาก 3D ได้ แต่ยังฝึกพิมพ์ได้ตามปกติ';});


